select

from survey_investigator_case a
where id = #{id,jdbcType=BIGINT}

select

from survey_investigator_case a
where a.delete_flag = 0
  and a.survey_info_id = #{surveyInfoId,jdbcType=BIGINT}
  and a.survey_user_id = #{surveyUserId,jdbcType=BIGINT}
order by a.id desc limit 1

select o.survey_org_id as orgId, o.survey_org_name as orgName, IFNULL((IFNULL(o.survey_money_submit,0) + IFNULL(o.survery_re_losses_submit,0)), 0)as money, r.survey_no as surveyNo, s.survey_person as surveyPerson, s.survery_person_tel as surveryPersonTel, r.entrust_org_name as entrustOrgName, s.entrust_user_name as entrustUserName, DATE_FORMAT(o.report_date,'%Y-%m-%d') as orgStartTimeStr, DATE_FORMAT(o.org_end_time,'%Y-%m-%d') as orgEndTimeStr, DATE_FORMAT(r.entrust_start_date,'%Y-%m-%d') as caseStartTimeStr, DATE_FORMAT(r.entrust_report_start_date,'%Y-%m-%d') as surveyDateStr, o.aging_real as caseDays,o.aging_check agingCheck,o.aging_over agingOver, DATE_FORMAT(r.entrust_report_end_date,'%Y-%m-%d') as entrustDateStr, DATE_FORMAT(o.create_time,'%Y-%m-%d') as orgCreateTimeStr, ifnull(n.efficiency_attr,2) as efficiencyAttr, o.create_time orgCreateTimeStr, MAX((case d.area_type when 1 then (case d.region_type when 5 then 0 else 1 end) else d.area_type end)) areaType,s.survey_case_no surveyCaseNo from survey_assign_org o left join survey_franchisee f on o.survey_org_id = f.id left join survey_risk_case_info r on o.survey_info_id = r.id left join survey_risk_case s on r.survey_id = s.id left join survey_consignor n on s.entrust_org_id = n.id LEFT JOIN survey_case_direction d ON o.id = d.survey_assorg_case_id where 1 = 1
and (f.id = #{orgId,jdbcType=BIGINT} or f.parent_id = #{orgId,jdbcType=BIGINT}) GROUP BY o.id order by IFNULL((IFNULL(o.survey_money_submit,0) + IFNULL(o.survery_re_losses_submit,0)), 0) desc
limit #{pageIndex}, #{pageSize}

select a.survey_org_id as orgId, a.survey_org_name as orgName, (case f.parent_id when 0 then f.id else f.parent_id end) as parentOrgId, (case f.parent_id when 0 then f.name else f.parent_name end) as parentOrgName, IFNULL((IFNULL(a.survey_money_submit,0) + IFNULL(a.survery_re_losses_submit,0)), 0)as money, r.survey_no as surveyNo, kk.isSun as isSun, r.survey_person as surveyPerson, r.survery_person_tel as surveryPersonTel, r.entrust_org_name as entrustOrgName, r.entrust_user_name as entrustUserName, DATE_FORMAT(a.report_date,'%Y-%m-%d') as orgStartTimeStr, DATE_FORMAT(a.org_end_time,'%Y-%m-%d') as orgEndTimeStr, DATE_FORMAT(r.entrust_time,'%Y-%m-%d') as caseStartTimeStr, DATE_FORMAT(s.entrust_report_start_date,'%Y-%m-%d') as surveyDateStr, get_date_interval(r.entrust_time,s.entrust_report_start_date) as caseDays, DATE_FORMAT(s.entrust_report_end_date,'%Y-%m-%d') as entrustDateStr, DATE_FORMAT(a.create_time,'%Y-%m-%d') as orgCreateTimeStr, s.id as surveyInfoId, IFNULL(t.areaType,4) as areaType, a.aging_real as orgDays,a.aging_check agingDay, a.aging_over agingOver, ifnull(c.efficiency_attr,2) as efficiencyAttr, DATE_FORMAT(a.utter_end_time,'%Y-%m-%d') as utterEndTime, a.id as surveyAssignOrgId, b.remarkAll , a.services_id as servicesId,a.services_name servicesName, b.extension_state as extensionState, a.overdue_aging_rate as overdueAgingRate, r.survey_case_no as surveyCaseNo, IFNULL((IFNULL(a.assess_org_money,0) + IFNULL(a.assess_org_losses_money,0)), 0)as assessMoney, si.surveyUserName as surveyUserName from survey_assign_org a left join survey_franchisee f on a.survey_org_id = f.id left join survey_risk_case_info s on a.survey_info_id = s.id left join survey_risk_case r on a.survey_id = r.id left join survey_consignor c on s.entrust_org_id = c.id left join ( select a.survey_info_id,a.org_id,max(a.area_type) as areaType from ( select d.id,d.survey_info_id,o.survey_org_id as org_id,(case d.area_type when 1 then (case d.region_type when 5 then 0 else 1 end) else d.area_type end) area_type from survey_case_direction d left join survey_assign_org o on d.survey_assorg_case_id = o.id left join survey_franchisee f on o.survey_org_id = f.id left join survey_risk_case_info r on o.survey_info_id = r.id left join survey_consignor n on r.entrust_org_id = n.id where d.delete_flag = 0 and f.id is not null and r.delete_flag = 0 ) a group by a.survey_info_id,a.org_id ) t on t.survey_info_id = a.survey_info_id and t.org_id = a.survey_org_id
left join ( SELECT a.survey_info_id,a.org_id,a.isSun FROM ( SELECT d.survey_info_id,d.survey_org_id AS org_id,d.is_sun AS isSun FROM survey_investigator_case d LEFT JOIN survey_franchisee f ON d.survey_org_id = f.id LEFT JOIN survey_risk_case_info r ON d.survey_info_id = r.id LEFT JOIN survey_consignor n ON r.entrust_org_id = n.id WHERE d.delete_flag = 0 AND f.id IS NOT NULL AND r.delete_flag = 0 AND d.is_sun >0 ) a GROUP BY a.survey_info_id,a.org_id ) kk on kk.survey_info_id = a.survey_info_id and kk.org_id = a.survey_org_id
LEFT JOIN ( select GROUP_CONCAT('(',create_time,')',extension_reason,'\r\n' ORDER BY create_time DESC) remarkAll,survey_assign_org_id,extension_state from survey_assign_org_extension WHERE delete_flag = 0 and extension_state = 2 GROUP BY survey_assign_org_id ) b ON b.survey_assign_org_id = a.id
LEFT JOIN ( select GROUP_CONCAT(survey_user_name) as surveyUserName, survey_assorg_case_id from survey_investigator_case WHERE delete_flag = 0 GROUP BY survey_assorg_case_id ) si ON si.survey_assorg_case_id = a.id where 1 = 1
and (find_in_set(f.id,#{surveyOrgIds,jdbcType=VARCHAR}) or find_in_set(f.parent_id,#{surveyOrgIds,jdbcType=VARCHAR}))
and s.entrust_report_end_date is not null
and DATE_FORMAT(s.entrust_report_end_date,'%Y-%m') >= #{startDate,jdbcType=VARCHAR}
and DATE_FORMAT(s.entrust_report_end_date,'%Y-%m') <= #{endDate,jdbcType=VARCHAR}
and s.entrust_report_start_date is not null
and DATE_FORMAT(s.entrust_report_start_date,'%Y-%m') >= #{startDate,jdbcType=VARCHAR}
and DATE_FORMAT(s.entrust_report_start_date,'%Y-%m') <= #{endDate,jdbcType=VARCHAR}
and find_in_set(s.source_support_type,#{sourceSupportTypes,jdbcType=VARCHAR})
and (a.survey_pay = 0 or a.survey_pay is null) AND s.delete_flag = 0 AND a.delete_flag = 0 order by a.survey_org_id,IFNULL((IFNULL(a.survey_money_submit,0) + IFNULL(a.survery_re_losses_submit,0)), 0) desc

