SELECT t.org_id as orgId, t.org_name as orgName, IFNULL((IFNULL(s.entrust_ok_price_1,0) + IFNULL(s.entrust_ok_price_2,0)), 0) AS entrustMoney, t.caseId as surveyInvestigatorCaseId, r.survey_no as surveyNo, r.survey_person as surveyPerson, r.survery_person_tel as surveryPersonTel, r.entrust_org_name as entrustOrgName, r.entrust_user_name as entrustUserName FROM ( SELECT i.org_name, i.org_id, a.survey_info_id,a.id as caseId FROM survey_investigator_case a LEFT JOIN survey_investigator i ON a.survey_user_id = i.user_id WHERE a.delete_flag = 0 GROUP BY i.org_id, i.org_name, a.survey_info_id ) t LEFT JOIN survey_risk_case_info s ON t.survey_info_id = s.id left join survey_risk_case r on s.survey_id = r.id WHERE 1= 1
and DATE_FORMAT(s.entrust_report_end_date,'%Y-%m-%d') >= DATE_FORMAT(#{startDate,jdbcType=DATE},'%Y-%m-%d')
and DATE_FORMAT(s.entrust_report_end_date,'%Y-%m-%d') <= DATE_FORMAT(#{endDate,jdbcType=DATE},'%Y-%m-%d')
AND s.delete_flag = 0 AND s.entrust_report_end_date is not null and t.org_id = #{orgId,jdbcType=BIGINT}
limit #{pageIndex}, #{pageSize}

SELECT i.survey_user_id as userId,i.survey_user_name as userName,sum(score) as score FROM ( SELECT * FROM survey_case_direction d WHERE d.survey_info_id IN ( SELECT s.id FROM survey_risk_case_info s WHERE 1 = 1
and DATE_FORMAT(s.entrust_report_end_date,'%Y-%m-%d') >= DATE_FORMAT(#{startDate,jdbcType=DATE},'%Y-%m-%d')
and DATE_FORMAT(s.entrust_report_end_date,'%Y-%m-%d') <= DATE_FORMAT(#{endDate,jdbcType=DATE},'%Y-%m-%d')
and DATE_FORMAT(s.entrust_report_end_date,'%Y-%m') = #{searchMonth,jdbcType=VARCHAR}
AND s.delete_flag = 0 and s.source_support_type = #{sourceyType,jdbcType=INTEGER} ) AND d.delete_flag = 0 ) A LEFT JOIN survey_investigator_case i ON A.survey_investigator_case_id = i.id AND i.delete_flag = 0 WHERE i.survey_user_id IN ( SELECT r.user_id FROM survey_investigator r WHERE r.org_id in (29,31) ) group by i.survey_user_id,i.survey_user_name;

select

from
survey_investigator_case a
where a.survey_info_id = #{surveyInfoId,jdbcType=BIGINT} and a.survey_org_id = #{surveyOrgId,jdbcType=BIGINT}
and a.survey_user_id != #{surveyUserId,jdbcType=BIGINT}
and a.delete_flag = 0

select

from
survey_investigator_case a
where a.survey_info_id = #{surveyInfoId,jdbcType=BIGINT}
and a.survey_assorg_case_id = #{surveyAssorgCaseId,jdbcType=BIGINT}
and a.id != #{id,jdbcType=BIGINT}
and a.delete_flag = 0

select si.real_name as surveyUserName, si.user_id as surveyUserId, si.org_id as surveyOrgId, si.org_name as surveyOrgName, IFNULL(x.caseNum,0) as caseNum, IFNULL(x.surveyScore,0) AS surveyScore, IFNULL(x.sunScore,0) as sunScore, IFNULL(x.scoreSum,0) as scoreSum, #{orgCaseState,jdbcType=BIGINT} as orgCaseState, #{surveyState,jdbcType=INTEGER} as surveyState, #{caseState,jdbcType=BIGINT} as caseState, #{entrustOrgIds,jdbcType=VARCHAR} as entrustOrgIds,#{entrustOrgName,jdbcType=VARCHAR} as entrustOrgName, ifnull(ch.channelCaseNum, 0) as channelCaseNum, case when #{surveyState,jdbcType=INTEGER} = 24 then '平台复审通过' when #{surveyState,jdbcType=INTEGER} = 28 then '保司终审通过' end as surveyStateName, case when #{caseState,jdbcType=BIGINT} = 0 then '全部' when #{caseState,jdbcType=BIGINT} = 1 then '单点' when #{caseState,jdbcType=BIGINT} = 2 then '单点+单点' when #{caseState,jdbcType=BIGINT} = 3 then '全案' when #{caseState,jdbcType=BIGINT} = 4 then '全案+单点' when #{caseState,jdbcType=BIGINT} = 5 then '全案+全案' end as caseStateName, case when #{orgCaseState,jdbcType=BIGINT} = 0 then '全部' when #{orgCaseState,jdbcType=BIGINT} = 1 then '单点' when #{orgCaseState,jdbcType=BIGINT} = 2 then '全案' end as orgCaseStateName from survey_investigator si left join ( select count(c.id) as caseNum ,sum(IFNULL(c.bs_score,0) + IFNULL(c.other_score,0)) AS surveyScore, sum(c.score_sun) as sunScore, sum(c.score) as scoreSum, c.survey_user_id as surveyUserId from survey_investigator_case c LEFT JOIN survey_risk_case_info a on a.id = c.survey_info_id LEFT JOIN survey_assign_org b on c.survey_assorg_case_id = b.id LEFT JOIN survey_consignor sc ON a.entrust_org_id = sc.id where a.delete_flag = 0 and c.delete_flag = 0 and b.delete_flag = 0 and sc.org_attr = #{orgAttr,jdbcType=BIGINT}
group by c.survey_user_id ) x on x.surveyUserId = si.user_id
left join ( select count(c.id) as channelCaseNum, c.survey_user_id as surveyUserId from survey_investigator_case c LEFT JOIN survey_risk_case_info a on a.id = c.survey_info_id LEFT JOIN survey_assign_org b on c.survey_assorg_case_id = b.id left join ( select (case when min(ifnull(d.channel_type,0)) = 0 then 0 else 1 end) as channelType,d.survey_assorg_case_id from survey_case_direction d group by d.survey_assorg_case_id ) t on b.id = t.survey_assorg_case_id LEFT JOIN survey_consignor sc ON a.entrust_org_id = sc.id where a.delete_flag = 0 and c.delete_flag = 0 and b.delete_flag = 0 and t.channelType = 1 and sc.org_attr = #{orgAttr,jdbcType=BIGINT}
group by c.survey_user_id ) ch on ch.surveyUserId = si.user_id
left join bus_user_role bur on bur.user_id = si.user_id where si.delete_flag = 0 and bur.role_id = 50
and find_in_set(si.user_id,#{surveyInvestigators,jdbcType=VARCHAR})
and si.org_id = #{orgId,jdbcType=BIGINT}
order by scoreSum desc

select f.name as surveyOrgName, f.id as surveyOrgId, f.level as orgLevel, ifnull(caseNum, 0) as caseNum, (case when a.surveyOrgId is null then 2 else 1 end) as orgType, ifnull((z.bsScore + z.otherScore), 0) AS surveyScore, ifnull(z.sunScore, 0) AS sunScore, ifnull(z.score, 0) AS scoreSum, #{orgCaseState,jdbcType=BIGINT} as orgCaseState, #{surveyState,jdbcType=INTEGER} as surveyState, #{caseState,jdbcType=BIGINT} as caseState, #{entrustOrgIds,jdbcType=VARCHAR} as entrustOrgIds, #{entrustOrgName,jdbcType=VARCHAR} as entrustOrgName, ifnull(ch.channelCaseNum, 0) as channelCaseNum, case when #{surveyState,jdbcType=INTEGER} = 24 then '平台复审通过' when #{surveyState,jdbcType=INTEGER} = 28 then '保司终审通过' end as surveyStateName, case when #{caseState,jdbcType=BIGINT} = 0 then '全部' when #{caseState,jdbcType=BIGINT} = 1 then '单点' when #{caseState,jdbcType=BIGINT} = 2 then '单点+单点' when #{caseState,jdbcType=BIGINT} = 3 then '全案' when #{caseState,jdbcType=BIGINT} = 4 then '全案+单点' when #{caseState,jdbcType=BIGINT} = 5 then '全案+全案' end as caseStateName, case when #{orgCaseState,jdbcType=BIGINT} = 0 then '全部' when #{orgCaseState,jdbcType=BIGINT} = 1 then '单点' when #{orgCaseState,jdbcType=BIGINT} = 2 then '全案' end as orgCaseStateName from survey_franchisee f
left join ( select survey_org_id as surveyOrgId from survey_org_area area where state = 1 and delete_flag = 0 group by survey_org_id ) a on f.id = a.surveyOrgId
left join ( select m.orgId as orgId, sum(m.score) as score, sum(m.bsScore) as bsScore, sum(m.otherScore) as otherScore, sum(m.sunScore) as sunScore, count(1) as caseNum from ( select t.orgId, sum(ifnull(t.score,0)) as score, sum(ifnull(t.bsScore,0)) as bsScore, sum(ifnull(t.otherScore,0)) as otherScore,sum(ifnull(t.sunScore,0)) as sunScore from( select c.score as score, c.bs_score as bsScore,c.other_score as otherScore, (case f.level when 2 then f.parent_id else b.survey_org_id end) as orgId, b.survey_org_id as orgId, c.score_sun as sunScore, a.id as surveyInfoId from survey_assign_org b left join survey_risk_case_info a on b.survey_info_id = a.id left join survey_investigator_case c on b.id = c.survey_assorg_case_id and c.delete_flag = 0 left join survey_franchisee f on b.survey_org_id = f.id left join survey_consignor sc on a.entrust_org_id = sc.id where b.delete_flag = 0 and a.delete_flag = 0 and sc.org_attr = #{orgAttr,jdbcType=BIGINT}
) t group by t.orgId, t.surveyInfoId ) m group by m.orgId ) z on f.id = z.orgId
left join ( select m.orgId as orgId, count(1) as channelCaseNum from ( select t.orgId from( select (case f.level when 2 then f.parent_id else b.survey_org_id end) as orgId, b.survey_org_id as orgId, a.id as surveyInfoId from survey_assign_org b left join ( select (case when min(ifnull(d.channel_type,0)) = 0 then 0 else 1 end) as channelType,d.survey_assorg_case_id from survey_case_direction d group by d.survey_assorg_case_id ) t on b.id = t.survey_assorg_case_id left join survey_risk_case_info a on b.survey_info_id = a.id left join survey_franchisee f on b.survey_org_id = f.id left join survey_consignor sc on a.entrust_org_id = sc.id where b.delete_flag = 0 and a.delete_flag = 0 and t.channelType = 1 and sc.org_attr = #{orgAttr,jdbcType=BIGINT}
) t group by t.orgId, t.surveyInfoId ) m group by m.orgId ) ch on f.id = ch.orgId
where f.delete_flag = 0 and f.org_state = 0
and f.bus_type in (1,3)
and f.bus_type in (2,3)
and f.parent_id = 0 and f.delete_flag = 0
and f.parent_id = #{orgId,jdbcType=BIGINT} or f.id = #{orgId,jdbcType=BIGINT}
and find_in_set(f.id,#{surveyOrgIds,jdbcType=VARCHAR})
and f.id = #{dataRoleOrgId,jdbcType=BIGINT}
order by scoreSum desc

select A.surveyOrgName as surveyOrgName, A.areaOrgId as surveyOrgId, A.orgLevel as orgLevel, sum(A.caseNum) as caseNum, sum(A.surveyScore) AS surveyScore, sum(A.sunScore) AS sunScore, sum(A.scoreSum) AS scoreSum, #{orgCaseState,jdbcType=BIGINT} as orgCaseState, #{surveyState,jdbcType=INTEGER} as surveyState, #{caseState,jdbcType=BIGINT} as caseState, #{entrustOrgIds,jdbcType=VARCHAR} as entrustOrgIds, #{entrustOrgName,jdbcType=VARCHAR} as entrustOrgName, sum(A.channelCaseNum) as channelCaseNum, case when #{surveyState,jdbcType=INTEGER} = 24 then '平台复审通过' when #{surveyState,jdbcType=INTEGER} = 28 then '保司终审通过' end as surveyStateName, case when #{caseState,jdbcType=BIGINT} = 0 then '全部' when #{caseState,jdbcType=BIGINT} = 1 then '单点' when #{caseState,jdbcType=BIGINT} = 2 then '单点+单点' when #{caseState,jdbcType=BIGINT} = 3 then '全案' when #{caseState,jdbcType=BIGINT} = 4 then '全案+单点' when #{caseState,jdbcType=BIGINT} = 5 then '全案+全案' end as caseStateName, case when #{orgCaseState,jdbcType=BIGINT} = 0 then '全部' when #{orgCaseState,jdbcType=BIGINT} = 1 then '单点' when #{orgCaseState,jdbcType=BIGINT} = 2 then '全案' end as orgCaseStateName
from(
select f.name as surveyOrgName, f.id as surveyOrgId, f.level as orgLevel, ifnull(caseNum, 0) as caseNum, ifnull((z.bsScore + z.otherScore), 0) AS surveyScore, ifnull(z.sunScore, 0) AS sunScore, ifnull(z.score, 0) AS scoreSum, ifnull(ch.channelCaseNum, 0) as channelCaseNum, ifnull(area.survey_area_id, area.org_id) as areaOrgId from survey_investigator area
left join survey_franchisee f on area.org_id = f.id left join ( select m.orgId as orgId, m.userId as userId, sum(m.score) as score, sum(m.bsScore) as bsScore, sum(m.otherScore) as otherScore, sum(m.sunScore) as sunScore, count(1) as caseNum from ( select t.orgId, t.userId, sum(ifnull(t.score,0)) as score, sum(ifnull(t.bsScore,0)) as bsScore, sum(ifnull(t.otherScore,0)) as otherScore,sum(ifnull(t.sunScore,0)) as sunScore from( select c.score as score, c.bs_score as bsScore,c.other_score as otherScore, ifnull(i.survey_area_id, i.org_id) as orgId, c.score_sun as sunScore, a.id as surveyInfoId, i.user_id as userId from survey_investigator_case c left join survey_investigator i on c.survey_user_id = i.user_id left join survey_assign_org b on c.survey_assorg_case_id = b.id left join survey_risk_case_info a on c.survey_info_id = a.id left join survey_consignor sc on a.entrust_org_id = sc.id where b.delete_flag = 0 and a.delete_flag = 0 and sc.org_attr = #{orgAttr,jdbcType=BIGINT}
) t group by t.orgId, t.surveyInfoId ) m group by m.orgId ) z on area.user_id = z.userId
left join ( select m.orgId as orgId,m.userId as userId, count(1) as channelCaseNum from ( select t.orgId, t.userId from( select ifnull(i.survey_area_id, i.org_id) as orgId, a.id as surveyInfoId,i.user_id as userId from survey_investigator i left join survey_investigator_case c on i.user_id = c.survey_user_id left join ( select (case when min(ifnull(d.channel_type,0)) = 0 then 0 else 1 end) as channelType,d.survey_investigator_case_id from survey_case_direction d group by d.survey_investigator_case_id ) t on c.id = t.survey_investigator_case_id left join survey_risk_case_info a on c.survey_info_id = a.id left join survey_assign_org b on c.survey_assorg_case_id = b.id left join survey_franchisee f on b.survey_org_id = f.id left join survey_consignor sc on a.entrust_org_id = sc.id where b.delete_flag = 0 and a.delete_flag = 0 and t.channelType = 1 and c.delete_flag = 0 and sc.org_attr = #{orgAttr,jdbcType=BIGINT}
) t group by t.orgId, t.surveyInfoId ) m group by m.orgId ) ch on area.user_id = ch.userId
where f.delete_flag = 0 and f.org_state = 0
and f.bus_type in (1,3)
and f.bus_type in (2,3)
and f.parent_id = 0 and f.delete_flag = 0
and f.parent_id = #{orgId,jdbcType=BIGINT} or f.id = #{orgId,jdbcType=BIGINT}
and find_in_set(f.id,#{surveyOrgIds,jdbcType=VARCHAR})
and f.id = #{dataRoleOrgId,jdbcType=BIGINT}
order by scoreSum desc ) A group by areaOrgId

select investigator.surveyUserName as surveyUserName, investigator.surveyUserId as surveyUserId, investigator.surveyOrgId as surveyOrgId, investigator.surveyOrgName as surveyOrgName, IFNULL(investigator.caseNum,0) as caseNum, IFNULL(investigator.surveyScore,0) AS surveyScore, IFNULL(investigator.sunScore,0) as sunScore, IFNULL(investigator.scoreSum,0) as scoreSum, #{orgCaseState,jdbcType=BIGINT} as orgCaseState, #{surveyState,jdbcType=INTEGER} as surveyState, #{caseState,jdbcType=BIGINT} as caseState, #{entrustOrgIds,jdbcType=VARCHAR} as entrustOrgIds,#{entrustOrgName,jdbcType=VARCHAR} as entrustOrgName, ifnull(ch.channelCaseNum, 0) as channelCaseNum, case when #{surveyState,jdbcType=INTEGER} = 24 then '平台复审通过' when #{surveyState,jdbcType=INTEGER} = 28 then '保司终审通过' end as surveyStateName, case when #{caseState,jdbcType=BIGINT} = 0 then '全部' when #{caseState,jdbcType=BIGINT} = 1 then '单点' when #{caseState,jdbcType=BIGINT} = 2 then '单点+单点' when #{caseState,jdbcType=BIGINT} = 3 then '全案' when #{caseState,jdbcType=BIGINT} = 4 then '全案+单点' when #{caseState,jdbcType=BIGINT} = 5 then '全案+全案' end as caseStateName, case when #{orgCaseState,jdbcType=BIGINT} = 0 then '全部' when #{orgCaseState,jdbcType=BIGINT} = 1 then '单点' when #{orgCaseState,jdbcType=BIGINT} = 2 then '全案' end as orgCaseStateName from ( select t.surveyUserId,t.surveyOrgId,t.surveyUserName, sum(t.bsScore + t.otherScore) AS surveyScore, sum(t.scoreSun) as sunScore, sum(t.scoreSum) as scoreSum, count(t.id) as caseNum, t.surveyOrgName from ( select c.id as id, si.user_id as surveyUserId, si.real_name as surveyUserName,si.org_id as surveyOrgId, IFNULL(c.bs_score,0) as bsScore, IFNULL(c.other_score,0) as otherScore,IFNULL(c.score_sun,0) as scoreSun, IFNULL(c.score,0) as scoreSum, b.survey_org_name as surveyOrgName from survey_investigator_case c LEFT JOIN survey_assign_org b on c.survey_assorg_case_id = b.id LEFT JOIN survey_risk_case_info a on a.id = c.survey_info_id LEFT JOIN survey_investigator si on si.user_id = c.survey_user_id LEFT JOIN survey_consignor sc ON a.entrust_org_id = sc.id where c.delete_flag= 0 and a.delete_flag = 0 and b.delete_flag= 0 AND sc.org_attr = #{orgAttr,jdbcType=BIGINT}
and si.survey_area_id =#{orgId,jdbcType=BIGINT} and (si.org_id = #{orgId,jdbcType=BIGINT} and si.survey_area_id is null)
) t GROUP BY t.surveyOrgId,t.surveyUserId )investigator
left join ( select t.surveyUserId,t.surveyOrgId,t.surveyUserName, count(t.id) as channelCaseNum, t.surveyOrgName from ( select c.id as id, si.user_id as surveyUserId, si.real_name as surveyUserName,si.org_id as surveyOrgId, IFNULL(c.bs_score,0) as bsScore, IFNULL(c.other_score,0) as otherScore,IFNULL(c.score_sun,0) as scoreSun, IFNULL(c.score,0) as scoreSum, b.survey_org_name as surveyOrgName from survey_investigator_case c LEFT JOIN survey_assign_org b on c.survey_assorg_case_id = b.id left join ( select (case when min(ifnull(d.channel_type,0)) = 0 then 0 else 1 end) as channelType,d.survey_assorg_case_id from survey_case_direction d group by d.survey_assorg_case_id ) t on b.id = t.survey_assorg_case_id LEFT JOIN survey_risk_case_info a on a.id = c.survey_info_id LEFT JOIN survey_investigator si on si.user_id = c.survey_user_id LEFT JOIN survey_consignor sc ON a.entrust_org_id = sc.id where c.delete_flag= 0 and a.delete_flag = 0 and b.delete_flag= 0 AND sc.org_attr = #{orgAttr,jdbcType=BIGINT}
and si.survey_area_id =#{orgId,jdbcType=BIGINT} and (si.org_id = #{orgId,jdbcType=BIGINT} and si.survey_area_id is null)
and t.channelType = 1
) t GROUP BY t.surveyOrgId,t.surveyUserId )ch on investigator.surveyUserId = ch.surveyUserId

select t.surveyInfoId as surveyInfoId, t.assignCaseId as assignCaseId, t.surveyNo as surveyNo, t.surveyPerson as surveyPerson, t.orgAssignDate as orgAssignDate, t.orgCreportDate as orgCreportDate, t.orgEndTime as orgEndTime,t.orgDays as orgDays, t.orgTaskRemark as orgTaskRemark, t.orgId as orgId, t.orgCaseState as orgCaseState, t.orgCaseStateName as orgCaseStateName, sum(t.bsScore + t.otherScore) as orgBaseScore, sum(t.orgSunScore) as orgSunScore, sum(t.orgScore) as orgScore, t.entrustOrgName as entrustOrgName from ( select a.id as surveyInfoId, b.id as assignCaseId, a.survey_no as surveyNo, r.survey_person as surveyPerson, b.create_time as orgAssignDate, b.report_date as orgCreportDate, b.org_end_time as orgEndTime, b.aging_real as orgDays,b.org_task_remark as orgTaskRemark, IFNULL(c.bs_score,0) as bsScore, IFNULL(c.other_score,0) as otherScore, IFNULL(c.score_sun,0) as orgSunScore,IFNULL(c.score,0) as orgScore, r.entrust_org_name as entrustOrgName, (case f.parent_id when 0 then f.id else f.parent_id end) as orgId, case when b.services_id = 11 then '1' when b.services_id = 12 then '1' when b.services_id = 13 then '2' end as orgCaseState, case when b.services_id = 11 then '单点' when b.services_id = 12 then '单点' when b.services_id = 13 then '全案' end as orgCaseStateName from survey_assign_org b
left join ( select (case when min(ifnull(d.channel_type,0)) = 0 then 0 else 1 end) as channelType,d.survey_assorg_case_id from survey_case_direction d group by d.survey_assorg_case_id ) t on b.id = t.survey_assorg_case_id
left join survey_risk_case_info a on b.survey_info_id = a.id left join survey_risk_case r on a.survey_id = r.id left join survey_investigator_case c on c.survey_assorg_case_id = b.id and c.delete_flag = 0 left join survey_investigator si on c.survey_user_id =si.user_id left join survey_franchisee f on b.survey_org_id = f.id left join survey_consignor sc on r.entrust_org_id = sc.id where b.delete_flag = 0 and a.delete_flag = 0 and sc.org_attr = #{orgAttr,jdbcType=BIGINT}
and ((b.survey_org_id in (select id from survey_franchisee where id = #{thisSurveyOrgId,jdbcType=BIGINT} or parent_id = #{thisSurveyOrgId,jdbcType=BIGINT})) or si.survey_area_id = #{thisSurveyOrgId,jdbcType=BIGINT})
and b.survey_org_id in (select id from survey_franchisee where id = #{thisSurveyOrgId,jdbcType=BIGINT} or parent_id = #{thisSurveyOrgId,jdbcType=BIGINT}) and si.survey_area_id is null
and si.survey_area_id = #{thisSurveyOrgId,jdbcType=BIGINT}
and t.channelType =1
) t group by t.orgId, t.surveyInfoId
limit #{pageIndex}, #{pageSize}

