) t group by t.orgId, t.surveyInfoId ) m

select f.name as surveyOrgName, f.id as surveyOrgId, f.level as orgLevel,(case when a.surveyOrgId is null then 2 else 1 end) as orgType, IFNULL(entrust.num,0) as entrustNum, IFNULL(upEntrust.num,0) as upEntrustNum, IFNULL(review.num,0) as reviewNum, IFNULL(upReview.num,0) as upReviewNum, IFNULL(zt.num,0) as ztNum, IFNULL(jjcq.num,0) as jjcqNum, IFNULL(cqdhf.num,0) as cqdhfNum,IFNULL(yzcq.num,0) as yzcqNum, IFNULL(yx.num,0) as yxNum,
from survey_franchisee f
left join ( select survey_org_id as surveyOrgId from survey_org_area area where state = 1 and delete_flag = 0 group by survey_org_id ) a on f.id = a.surveyOrgId
left join ( select m.orgId, count(1) as num from ( select t.orgId, t.survey_info_id from( select b.survey_info_id as survey_info_id, CASE WHEN f.parent_id != 0 THEN f.parent_id ELSE f.id END AS orgId f.id AS orgId from survey_assign_org b left join survey_risk_case_info a on b.survey_info_id = a.id left join survey_risk_case r on a.survey_id = r.id left join survey_franchisee f on b.survey_org_id = f.id left join survey_consignor sc on r.entrust_org_id = sc.id where b.delete_flag = 0 and a.delete_flag = 0 and sc.org_attr = #{orgAttr}
