) t group by t.orgId, t.survey_info_id ) m group by m.orgId ) entrust on f.id = entrust.orgId
left join ( select m.orgId, count(1) as num from ( select t.orgId, t.survey_info_id from( select b.survey_info_id as survey_info_id, CASE WHEN f.parent_id != 0 THEN f.parent_id ELSE f.id END AS orgId f.id AS orgId from survey_assign_org b left join survey_risk_case_info a on b.survey_info_id = a.id left join survey_risk_case r on a.survey_id = r.id left join survey_franchisee f on b.survey_org_id = f.id left join survey_consignor sc on r.entrust_org_id = sc.id where b.delete_flag = 0 and a.delete_flag = 0 and sc.org_attr = #{orgAttr}
and date_format(r.entrust_time,'%Y-%m-%d') >= date_format(#{momTime,jdbcType=DATE},'%Y-%m-%d')
