AND a.entrust_report_start_date is not null
and b.review_time is not null
) t group by t.orgId, t.survey_info_id ) m group by m.orgId ) review on f.id = review.orgId
left join ( select m.orgId, count(1) as num from ( select t.orgId, t.survey_info_id from( select b.survey_info_id as survey_info_id, CASE WHEN f.parent_id != 0 THEN f.parent_id ELSE f.id END AS orgId f.id AS orgId from survey_assign_org b left join survey_risk_case_info a on b.survey_info_id = a.id left join survey_risk_case r on a.survey_id = r.id left join survey_franchisee f on b.survey_org_id = f.id left join survey_consignor sc on r.entrust_org_id = sc.id where b.delete_flag = 0 and a.delete_flag = 0 and sc.org_attr = #{orgAttr}
and date_format(r.entrust_time,'%Y-%m-%d') >= date_format(#{momTime,jdbcType=DATE},'%Y-%m-%d')
and date_format(r.entrust_time,'%Y-%m-%d') < date_format(#{startTime,jdbcType=DATE},'%Y-%m-%d')
AND a.entrust_report_start_date is not null
and b.review_time is not null
)t group by t.orgId, t.survey_info_id ) m group by m.orgId ) upReview on f.id = upReview.orgId
left join ( select m.orgId, count(1) as num from ( select t.orgId, t.survey_info_id from( select b.survey_info_id as survey_info_id, CASE WHEN f.parent_id != 0 THEN f.parent_id ELSE f.id END AS orgId f.id AS orgId from survey_assign_org b left join survey_risk_case_info a on b.survey_info_id = a.id left join survey_risk_case r on a.survey_id = r.id left join survey_franchisee f on b.survey_org_id = f.id left join survey_consignor sc on r.entrust_org_id = sc.id where b.delete_flag = 0 and a.delete_flag = 0 and sc.org_attr = #{orgAttr}
and date_format(r.entrust_time,'%Y-%m-%d') >= date_format(#{startTime,jdbcType=DATE},'%Y-%m-%d')
and date_format(r.entrust_time,'%Y-%m-%d') <= date_format(#{endTime,jdbcType=DATE},'%Y-%m-%d')
and b.report_date is null )t group by t.orgId, t.survey_info_id ) m group by m.orgId ) zt on f.id = zt.orgId
left join ( select m.orgId, count(1) as num from ( select t.orgId, t.survey_info_id from( select b.survey_info_id as survey_info_id, CASE WHEN f.parent_id != 0 THEN f.parent_id ELSE f.id END AS orgId f.id AS orgId from survey_assign_org b left join survey_risk_case_info a on b.survey_info_id = a.id left join survey_risk_case r on a.survey_id = r.id left join survey_franchisee f on b.survey_org_id = f.id left join survey_consignor sc on r.entrust_org_id = sc.id where b.delete_flag = 0 and a.delete_flag = 0 and sc.org_attr = #{orgAttr}
and date_format(r.entrust_time,'%Y-%m-%d') >= date_format(#{startTime,jdbcType=DATE},'%Y-%m-%d')
and date_format(r.entrust_time,'%Y-%m-%d') <= date_format(#{endTime,jdbcType=DATE},'%Y-%m-%d')
and b.report_date is null and TIMESTAMPDIFF(DAY,NOW(),DATE_FORMAT(b.org_end_time, '%Y-%m-%d %H:%i:%S')) >0 and TIMESTAMPDIFF(DAY,NOW(),DATE_FORMAT(b.org_end_time, '%Y-%m-%d %H:%i:%S')) <=2
and b.report_date is null and b.aging_check - b.aging_real > 0 and b.aging_check - b.aging_real <= 3 and b.aging_over =0
)t group by t.orgId, t.survey_info_id ) m group by m.orgId ) jjcq on f.id = jjcq.orgId
left join ( select m.orgId, count(1) as num from ( select t.orgId, t.survey_info_id from( select b.survey_info_id as survey_info_id, CASE WHEN f.parent_id != 0 THEN f.parent_id ELSE f.id END AS orgId f.id AS orgId from survey_assign_org b left join survey_risk_case_info a on b.survey_info_id = a.id left join survey_risk_case r on a.survey_id = r.id left join survey_franchisee f on b.survey_org_id = f.id left join survey_consignor sc on r.entrust_org_id = sc.id where b.delete_flag = 0 and a.delete_flag = 0 and sc.org_attr = #{orgAttr}
