left join ( select m.orgId as orgId, m.userId as userId, count(1) as num from ( select t.orgId, t.survey_info_id, t.userId from( select b.survey_info_id as survey_info_id, ifnull(i.survey_area_id, i.org_id) as orgId, i.user_id as userId from survey_investigator_case c left join survey_investigator i on c.survey_user_id = i.user_id left join survey_assign_org b on c.survey_assorg_case_id = b.id left join survey_risk_case_info a on b.survey_info_id = a.id left join survey_risk_case r on a.survey_id = r.id left join survey_consignor sc on r.entrust_org_id = sc.id where b.delete_flag = 0 and a.delete_flag = 0 and sc.org_attr = #{orgAttr}
