left join ( select m.orgId as orgId, m.userId as userId, count(1) as num from ( select t.orgId, t.survey_info_id, t.userId from( select b.survey_info_id as survey_info_id, ifnull(i.survey_area_id, i.org_id) as orgId, i.user_id as userId from survey_investigator_case c left join survey_investigator i on c.survey_user_id = i.user_id left join survey_assign_org b on c.survey_assorg_case_id = b.id left join survey_risk_case_info a on b.survey_info_id = a.id left join survey_risk_case r on a.survey_id = r.id left join survey_consignor sc on r.entrust_org_id = sc.id where b.delete_flag = 0 and a.delete_flag = 0 and sc.org_attr = #{orgAttr}
and date_format(r.entrust_time,'%Y-%m-%d') >= date_format(#{startTime,jdbcType=DATE},'%Y-%m-%d')
and date_format(r.entrust_time,'%Y-%m-%d') <= date_format(#{endTime,jdbcType=DATE},'%Y-%m-%d')
and b.report_date is null and TIMESTAMPDIFF(DAY,NOW(),DATE_FORMAT(b.org_end_time, '%Y-%m-%d %H:%i:%S')) >0 and TIMESTAMPDIFF(DAY,NOW(),DATE_FORMAT(b.org_end_time, '%Y-%m-%d %H:%i:%S')) <=2
and b.report_date is null and b.aging_check - b.aging_real > 0 and b.aging_check - b.aging_real <= 3 and b.aging_over =0
)t group by t.orgId, t.survey_info_id ) m group by m.orgId ) jjcq on area.user_id = jjcq.userId
left join ( select m.orgId as orgId, m.userId as userId, count(1) as num from ( select t.orgId, t.survey_info_id, t.userId from( select b.survey_info_id as survey_info_id, ifnull(i.survey_area_id, i.org_id) as orgId, i.user_id as userId from survey_investigator_case c left join survey_investigator i on c.survey_user_id = i.user_id left join survey_assign_org b on c.survey_assorg_case_id = b.id left join survey_risk_case_info a on b.survey_info_id = a.id left join survey_risk_case r on a.survey_id = r.id left join survey_consignor sc on r.entrust_org_id = sc.id where b.delete_flag = 0 and a.delete_flag = 0 and sc.org_attr = #{orgAttr}
and date_format(r.entrust_time,'%Y-%m-%d') >= date_format(#{startTime,jdbcType=DATE},'%Y-%m-%d')
and date_format(r.entrust_time,'%Y-%m-%d') <= date_format(#{endTime,jdbcType=DATE},'%Y-%m-%d')
and b.report_date is null and b.aging_over > 0 )t group by t.orgId, t.survey_info_id ) m group by m.orgId ) cqdhf on area.user_id = cqdhf.userId
left join ( select m.orgId as orgId, m.userId as userId, count(1) as num from ( select t.orgId, t.survey_info_id, t.userId from( select b.survey_info_id as survey_info_id, ifnull(i.survey_area_id, i.org_id) as orgId, i.user_id as userId from survey_investigator_case c left join survey_investigator i on c.survey_user_id = i.user_id left join survey_assign_org b on c.survey_assorg_case_id = b.id left join survey_risk_case_info a on b.survey_info_id = a.id left join survey_risk_case r on a.survey_id = r.id left join survey_consignor sc on r.entrust_org_id = sc.id where b.delete_flag = 0 and a.delete_flag = 0 and sc.org_attr = #{orgAttr}
and date_format(r.entrust_time,'%Y-%m-%d') >= date_format(#{startTime,jdbcType=DATE},'%Y-%m-%d')
and date_format(r.entrust_time,'%Y-%m-%d') <= date_format(#{endTime,jdbcType=DATE},'%Y-%m-%d')
and b.report_date is null and TIMESTAMPDIFF(DAY,b.org_end_time,DATE_FORMAT(NOW(), '%Y-%m-%d %H:%i:%S')) >=2
and b.report_date is null and b.aging_over >= 10
)t group by t.orgId, t.survey_info_id ) m group by m.orgId ) yzcq on area.user_id = yzcq.userId
left join ( select m.orgId as orgId, m.userId as userId, count(1) as num from ( select t.orgId, t.survey_info_id, t.userId from( select b.survey_info_id as survey_info_id, ifnull(i.survey_area_id, i.org_id) as orgId, i.user_id as userId from survey_investigator_case c left join survey_investigator i on c.survey_user_id = i.user_id left join survey_assign_org b on c.survey_assorg_case_id = b.id left join survey_risk_case_info a on b.survey_info_id = a.id left join survey_risk_case r on a.survey_id = r.id left join survey_consignor sc on r.entrust_org_id = sc.id where b.delete_flag = 0 and a.delete_flag = 0 and c.delete_flag = 0 and c.score_sun > 0 and b.review_time is not null and sc.org_attr = #{orgAttr}
and date_format(r.entrust_time,'%Y-%m-%d') >= date_format(#{startTime,jdbcType=DATE},'%Y-%m-%d')
and date_format(r.entrust_time,'%Y-%m-%d') <= date_format(#{endTime,jdbcType=DATE},'%Y-%m-%d')
)t group by t.orgId, t.survey_info_id ) m group by m.orgId ) yx on area.user_id = yx.userId
where f.delete_flag = 0 and f.org_state = 0
and f.bus_type in (2,3)
and f.bus_type in (1,3)
and f.parent_id = 0
and f.parent_id = #{orgId,jdbcType=BIGINT} or f.id = #{orgId,jdbcType=BIGINT}
and f.id = #{dataRoleOrgId,jdbcType=BIGINT}
and find_in_set(f.id,#{surveyOrgIds,jdbcType=VARCHAR})
) A group by areaOrgId

select a.id as surveyInfoId, b.id as assignCaseId, a.survey_no as surveyNo, r.survey_person as surveyPerson, b.create_time as orgAssignDate, b.report_date as orgCreportDate, b.org_end_time as orgEndTime, b.org_task_remark as orgTaskRemark, b.return_state as orgReturnState, b.aging_real as orgDays, r.entrust_org_name as entrustOrgName, b.org_survey_state as orgSurveyState, b.org_survey_state_name as orgSurveyStateName, b.org_task_remark as orgTaskRemark, b.review_user_id as reviewUserId, b.review_time as reviewTime, case when c.score_sun > 0 then '1' else '0' end as orgIsSun, case when b.services_id = 11 then '1' when b.services_id = 12 then '1' when b.services_id = 13 then '2' end as orgCaseState, case when b.services_id = 11 then '单点' when b.services_id = 12 then '单点' when b.services_id = 13 then '全案' end as orgCaseStateName, CASE WHEN f.parent_id != 0 THEN f.parent_id ELSE f.id END AS surveyOrgId from survey_assign_org b LEFT JOIN survey_franchisee f on b.survey_org_id = f.id left join survey_risk_case_info a on b.survey_info_id = a.id and a.delete_flag = 0 left join survey_risk_case r on a.survey_id = r.id and r.delete_flag = 0 left join survey_investigator_case c on c.survey_assorg_case_id = b.id and c.delete_flag = 0 left join survey_investigator si on c.survey_user_id =si.user_id left join survey_consignor sc on r.entrust_org_id = sc.id where b.delete_flag = 0 and sc.org_attr = #{orgAttr}
and ((b.survey_org_id in (select id from survey_franchisee where id = #{thisSurveyOrgId,jdbcType=BIGINT} or parent_id = #{thisSurveyOrgId,jdbcType=BIGINT})) or si.survey_area_id = #{thisSurveyOrgId,jdbcType=BIGINT})
and b.survey_org_id in (select id from survey_franchisee where id = #{thisSurveyOrgId,jdbcType=BIGINT} or parent_id = #{thisSurveyOrgId,jdbcType=BIGINT}) and si.survey_area_id is null
and si.survey_area_id = #{thisSurveyOrgId,jdbcType=BIGINT}
group by surveyOrgId, b.survey_info_id order by orgAssignDate
limit #{pageIndex}, #{pageSize}

select count(1) from ( select b.id as assignCaseId, CASE WHEN f.parent_id != 0 THEN f.parent_id ELSE f.id END AS surveyOrgId from survey_assign_org b LEFT JOIN survey_franchisee f on b.survey_org_id = f.id left join survey_risk_case_info a on b.survey_info_id = a.id and a.delete_flag = 0 left join survey_risk_case r on a.survey_id = r.id and r.delete_flag = 0 left join survey_investigator_case c on c.survey_assorg_case_id = b.id and c.delete_flag = 0 left join survey_investigator si on c.survey_user_id =si.user_id left join survey_consignor sc on r.entrust_org_id = sc.id where b.delete_flag = 0 and sc.org_attr = #{orgAttr}
and ((b.survey_org_id in (select id from survey_franchisee where id = #{thisSurveyOrgId,jdbcType=BIGINT} or parent_id = #{thisSurveyOrgId,jdbcType=BIGINT})) or si.survey_area_id = #{thisSurveyOrgId,jdbcType=BIGINT})
and b.survey_org_id in (select id from survey_franchisee where id = #{thisSurveyOrgId,jdbcType=BIGINT} or parent_id = #{thisSurveyOrgId,jdbcType=BIGINT}) and si.survey_area_id is null
and si.survey_area_id = #{thisSurveyOrgId,jdbcType=BIGINT}
group by surveyOrgId, b.survey_info_id ) t

select t.surveyInfoId as surveyInfoId, t.investigatorCaseId as investigatorCaseId, t.surveyNo as surveyNo, t.surveyPerson as surveyPerson, t.userAssignDate as userAssignDate, t.userCreportDate as userCreportDate, t.userEndTime as userEndTime, t.userDays as userDays, t.entrustOrgName as entrustOrgName, t.assignCaseId as assignCaseId, t.userSurveyState as userSurveyState, t.userSurveyStateName as userSurveyStateName,t.userReturnState,t.userIsSun from ( select a.id as surveyInfoId, c.id as investigatorCaseId, a.survey_no as surveyNo, r.survey_person as surveyPerson, c.assign_date as userAssignDate, c.creport_date as userCreportDate, c.survey_end_time as userEndTime, c.aging_real as userDays,c.survey_user_id as surveyUserId, c.survey_assorg_case_id as assignCaseId, c.survey_state as userSurveyState, c.survey_state_name as userSurveyStateName, c.return_state as userReturnState, case when c.score_sun > 0 then '1' else '0' end as userIsSun, r.entrust_org_name as entrustOrgName from survey_investigator_case c left join survey_risk_case_info a on c.survey_info_id = a.id and a.delete_flag = 0 left join survey_risk_case r on a.survey_id = r.id and r.delete_flag = 0 left join survey_assign_org b on b.survey_info_id = a.id and b.delete_flag = 0 left join survey_consignor sc on r.entrust_org_id = sc.id where c.delete_flag = 0 and sc.org_attr = #{orgAttr}
group by c.id ) t where t.surveyUserId = #{surveyUserId,jdbcType=VARCHAR} order by userAssignDate
limit #{pageIndex}, #{pageSize}

select count(1) from (
    select t.investigatorCaseId as investigatorCaseId
      from (
        select c.id as investigatorCaseId,c.survey_user_id as surveyUserId
        from  survey_investigator_case c
        left join survey_risk_case_info a on c.survey_info_id = a.id and a.delete_flag = 0
        left join survey_risk_case r on a.survey_id = r.id and r.delete_flag = 0
        left join survey_assign_org b on b.survey_info_id = a.id and b.delete_flag = 0
        left join survey_consignor sc on r.entrust_org_id = sc.id
        where c.delete_flag = 0 and sc.org_attr = #{orgAttr}

        group by c.id
      ) t
    where t.surveyUserId = #{surveyUserId,jdbcType=VARCHAR}
) d

SELECT a.survey_user_id as surveyUserId,c.review_time as reviewTime,IFNULL(a.score,0) score FROM survey_investigator_case a LEFT JOIN survey_risk_case_info b ON a.survey_info_id=b.id LEFT JOIN survey_assign_org c ON a.survey_assorg_case_id = c.id LEFT JOIN survey_consignor d ON a.entrust_org_id=d.id WHERE a.delete_flag=0 AND b.delete_flag=0 AND c.delete_flag=0 AND d.delete_flag=0 AND d.org_attr =2 AND c.review_time IS NOT NULL and d.org_state = 0
and a.survey_user_id = #{surveyUserId}
ORDER BY c.review_time

